CREATE TABLE `scan_findings` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `scan_job_id` bigint NOT NULL,
  `check_type` varchar(64) NOT NULL,
  `severity` varchar(16) NOT NULL,
  `affected_component` varchar(2048) NOT NULL,
  `evidence` varchar(1000) NOT NULL,
  `rationale` varchar(1000) NOT NULL,
  `remediation` varchar(1000) NOT NULL,
  `detection_source` varchar(64) NOT NULL,
  `verification_status` varchar(32) NOT NULL,
  `detected_at` datetime(6) NOT NULL,
  `source_rule_id` varchar(64) DEFAULT NULL,
  `source_confidence` varchar(16) DEFAULT NULL,
  `source_reference` varchar(2048) DEFAULT NULL,
  `source_cwe_id` varchar(16) DEFAULT NULL,
  `source_wasc_id` varchar(16) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_scan_findings_scan` (`scan_job_id`),
  CONSTRAINT `fk_scan_findings_job` FOREIGN KEY (`scan_job_id`) REFERENCES `scan_jobs` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1546 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
