--
-- Table structure for table `scan_jobs`
--

DROP TABLE IF EXISTS `scan_jobs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `scan_jobs` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `target_id` bigint NOT NULL,
  `organization_id` bigint NOT NULL,
  `requested_by_user_id` bigint NOT NULL,
  `scan_type` varchar(32) NOT NULL,
  `status` varchar(32) NOT NULL,
  `progress` int NOT NULL DEFAULT '0',
  `status_message` varchar(250) NOT NULL,
  `failure_reason` varchar(250) DEFAULT NULL,
  `cancellation_requested` tinyint(1) NOT NULL DEFAULT '0',
  `created_at` datetime(6) NOT NULL,
  `started_at` datetime(6) DEFAULT NULL,
  `completed_at` datetime(6) DEFAULT NULL,
  `reviewed_by_user_id` bigint DEFAULT NULL,
  `reviewed_at` datetime(6) DEFAULT NULL,
  `rejection_reason` varchar(1000) DEFAULT NULL,
  `native_engine_status` varchar(24) NOT NULL DEFAULT 'UNKNOWN',
  `zap_engine_status` varchar(24) NOT NULL DEFAULT 'UNKNOWN',
  `discovered_page_count` int DEFAULT NULL,
  `visited_page_count` int DEFAULT NULL,
  `tested_passive_page_count` int DEFAULT NULL,
  `nvd_lookup_status` varchar(24) NOT NULL DEFAULT 'NOT_REQUESTED',
  `zap_requested` tinyint(1) NOT NULL DEFAULT '0',
  `zap_failure_reason` varchar(250) DEFAULT NULL,
  `zap_spider_status` varchar(24) DEFAULT NULL,
  `zap_spider_discovered_count` int DEFAULT NULL,
  `zap_passive_status` varchar(24) DEFAULT NULL,
  `zap_alert_count` int DEFAULT NULL,
  `zap_active_status` varchar(24) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_scan_jobs_org_created` (`organization_id`,`created_at`),
  KEY `idx_scan_jobs_target` (`target_id`),
  KEY `fk_scan_jobs_requested_by` (`requested_by_user_id`),
  KEY `idx_scan_jobs_approval` (`organization_id`,`status`,`created_at`),
  KEY `fk_scan_jobs_reviewed_by` (`reviewed_by_user_id`),
  CONSTRAINT `fk_scan_jobs_organization` FOREIGN KEY (`organization_id`) REFERENCES `organizations` (`id`),
  CONSTRAINT `fk_scan_jobs_requested_by` FOREIGN KEY (`requested_by_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_scan_jobs_reviewed_by` FOREIGN KEY (`reviewed_by_user_id`) REFERENCES `users` (`id`),
  CONSTRAINT `fk_scan_jobs_target` FOREIGN KEY (`target_id`) REFERENCES `targets` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=55 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

